import sys

def main():
    data = sys.stdin.read().split()
    a, b = data[0], data[1]
    out = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            out.append(a[i])
        if i < len(b):
            out.append(b[i])
    print(''.join(out))

